3	use ruff_macros::{ViolationMetadata, derive_message_formats};
4	use ruff_python_ast as ast;
5	use ruff_python_ast::{Arguments, Expr};
6	use ruff_text_size::Ranged;
7	
8	use crate::checkers::ast::Checker;
9	use crate::fix::edits::pad;
10	use crate::{AlwaysFixableViolation, Edit, Fix};
