12	/// ## What it does
13	/// Checks for uses of `dict.items()` that discard either the key or the value
14	/// when iterating over the dictionary.
15	///
16	/// ## Why is this bad?
17	/// If you only need the keys or values of a dictionary, you should use
18	/// `dict.keys()` or `dict.values()` respectively, instead of `dict.items()`.
19	/// These specialized methods are more efficient than `dict.items()`, as they
20	/// avoid allocating tuples for every item in the dictionary. They also
21	/// communicate the intent of the code more clearly.
22	///
23	/// Note that, as with all `perflint` rules, this is only intended as a
24	/// micro-optimization, and will have a negligible impact on performance in
25	/// most cases.
26	///
27	/// ## Example
28	/// ```python
29	/// obj = {"a": 1, "b": 2}
30	/// for key, value in obj.items():
31	///     print(value)
32	/// ```
33	///
34	/// Use instead:
35	/// ```python
36	/// obj = {"a": 1, "b": 2}
37	/// for value in obj.values():
38	///     print(value)
39	/// ```
40	///
41	/// ## Fix safety
42	/// The fix does not perform any type analysis and, as such, may suggest an
43	/// incorrect fix if the object in question does not duck-type as a mapping
44	/// (e.g., if it is missing a `.keys()` or `.values()` method, or if those
45	/// methods behave differently than they do on standard mapping types).
46	#[derive(ViolationMetadata)]
47	#[violation_metadata(stable_since = "v0.0.273")]
48	pub(crate) struct IncorrectDictIterator {
49	    subset: DictSubset,
50	}
51	
52	impl AlwaysFixableViolation for IncorrectDictIterator {
53	    #[derive_message_formats]
54	    fn message(&self) -> String {
55	        let IncorrectDictIterator { subset } = self;
56	        format!("When using only the {subset} of a dict use the `{subset}()` method")
57	    }
58	
59	    fn fix_title(&self) -> String {
60	        let IncorrectDictIterator { subset } = self;
61	        format!("Replace `.items()` with `.{subset}()`")
62	    }
63	}
64	
65	/// PERF102
66	pub(crate) fn incorrect_dict_iterator(checker: &Checker, stmt_for: &ast::StmtFor) {
67	    let Expr::Tuple(ast::ExprTuple { elts, .. }) = stmt_for.target.as_ref() else {
68	        return;
69	    };
70	    let [key, value] = elts.as_slice() else {
71	        return;
72	    };
73	    let Expr::Call(ast::ExprCall {
74	        func,
75	        arguments: Arguments { args, .. },
76	        ..
77	    }) = stmt_for.iter.as_ref()
78	    else {
79	        return;
80	    };
81	    if !args.is_empty() {
82	        return;
83	    }
84	    let Expr::Attribute(ast::ExprAttribute { attr, .. }) = func.as_ref() else {
85	        return;
86	    };
87	    if attr != "items" {
88	        return;
89	    }
90	
91	    match (
92	        checker.semantic().is_unused(key),
93	        checker.semantic().is_unused(value),
94	    ) {
95	        (true, true) => {
96	            // Both the key and the value are unused.
97	        }
98	        (false, false) => {
99	            // Neither the key nor the value are unused.
100	        }
101	        (true, false) => {
102	            // The key is unused, so replace with `dict.values()`.
103	            let mut diagnostic = checker.report_diagnostic(
104	                IncorrectDictIterator {
105	                    subset: DictSubset::Values,
106	                },
107	                func.range(),
108	            );
109	            let replace_attribute = Edit::range_replacement("values".to_string(), attr.range());
110	            let replace_target = Edit::range_replacement(
111	                pad(
112	                    checker.locator().slice(value).to_string(),
113	                    stmt_for.target.range(),
114	                    checker.locator(),
115	                ),
116	                stmt_for.target.range(),
117	            );
118	            diagnostic.set_fix(Fix::unsafe_edits(replace_attribute, [replace_target]));
119	        }
120	        (false, true) => {
121	            // The value is unused, so replace with `dict.keys()`.
122	            let mut diagnostic = checker.report_diagnostic(
123	                IncorrectDictIterator {
124	                    subset: DictSubset::Keys,
125	                },
126	                func.range(),
127	            );
128	            let replace_attribute = Edit::range_replacement("keys".to_string(), attr.range());
129	            let replace_target = Edit::range_replacement(
130	                pad(
131	                    checker.locator().slice(key).to_string(),
132	                    stmt_for.target.range(),
133	                    checker.locator(),
134	                ),
135	                stmt_for.target.range(),
136	            );
137	            diagnostic.set_fix(Fix::unsafe_edits(replace_attribute, [replace_target]));
138	        }
139	    }
140	}
141	
142	#[derive(Debug, PartialEq, Eq)]
143	enum DictSubset {
144	    Keys,
145	    Values,
146	}
147	
148	impl fmt::Display for DictSubset {
149	    fn fmt(&self, fmt: &mut fmt::Formatter) -> fmt::Result {
150	        match self {
151	            DictSubset::Keys => fmt.write_str("keys"),
152	            DictSubset::Values => fmt.write_str("values"),
153	        }
154	    }
155	}
