2401	    /// generator expression, like a list or set comprehension.
2402	    fn visit_generators(&mut self, kind: GeneratorKind, generators: &'a [Comprehension]) {
2403	        let mut iterator = generators.iter();
2404	
2405	        let Some(generator) = iterator.next() else {
2406	            unreachable!("Generator expression must contain at least one generator");
2407	        };
2408	
2409	        let flags = self.semantic.flags;
2410	
2411	        // Generators are compiled as nested functions. (This may change with PEP 709.)
2412	        // As such, the `iter` of the first generator is evaluated in the outer scope, while all
2413	        // subsequent nodes are evaluated in the inner scope.
2414	        //
2415	        // For example, given:
2416	        // ```python
2417	        // class A:
2418	        //     T = range(10)
2419	        //
2420	        //     L = [x for x in T for y in T]
2421	        // ```
2422	        //
2423	        // Conceptually, this is compiled as:
2424	        // ```python
2425	        // class A:
2426	        //     T = range(10)
2427	        //
2428	        //     def foo(x=T):
2429	        //         def bar(y=T):
2430	        //             pass
2431	        //         return bar()
2432	        //     foo()
2433	        // ```
2434	        //
2435	        // Following Python's scoping rules, the `T` in `x=T` is thus evaluated in the outer scope,
2436	        // while all subsequent reads and writes are evaluated in the inner scope. In particular,
2437	        // `x` is local to `foo`, and the `T` in `y=T` skips the class scope when resolving.
2438	        self.visit_expr(&generator.iter);
2439	        self.semantic.push_scope(ScopeKind::Generator {
2440	            kind,
2441	            is_async: generators
2442	                .iter()
